"""AI attribution: this whole file was generated by Claude (Anthropic) in Claude Code, following
design decisions made by the author. See ATTRIBUTION.md for details.

Dev numbers for the revised freeze amendment and grounding package (independent AI review of the amendment,
fixes approved by the author 2026-11-20). Dev only, CPU; no training, no API; test and replication untouched.

A. Main-system choice (review item 3): R-hear grounded group accuracy (G1a statistic, 95% interval by the package's
   three-way cluster bootstrap) for every candidate, beside its natural dev five-part mean from the stored results.
B. Ladder with the natural-label control as the mean over its 8 fixed starts (scripts/p1v4_control_starts.py), at the
   score level (paired concordance, ties 0.5) and at the decision level (frozen thresholds): G2b, G3a, G3b, the
   absolute conditions (rung's own concordance minus 0.5), the side rows, and the main system.
C. Event-score difference (version 1 minus version 2 or 3; event score = 1 - P(respond)) per read-out, mean over
   the six matched conditions, with intervals; and the rung differences.
D. Cost of grounding: step 2 ears read-out minus step 2b ears read-out, natural dev five-part mean (plan 7.1 interval).
E. Answer-only losses of each Gemini rival on dev: five-part mean and the must-listen part; floors in both modes.
Output: results/main_v04/amendment_numbers_dev.json
usage (repo root): .venv-gpu/Scripts/python.exe -X utf8 scripts/p1v4_amendment_numbers_dev.py
"""
import json
import os
import sys

import numpy as np

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import p1v4_control_starts as CS  # noqa: E402
import p1v4_data as D  # noqa: E402
import p1v4_grounding as G  # noqa: E402
import p1v4_grounding_report as GR  # noqa: E402
import p1v4_readout as RO  # noqa: E402
import p1v4_readout_allclass as AC  # noqa: E402
import p1v4_score as S  # noqa: E402

RES = "results/main_v04"


def ci(c):
    return {"point": c["point"], "ci95": c["ci95"]}


def main():
    rows, rows_by = G.load("dev")
    groups = G.load_groups("dev")
    rh = [g for g in groups if g["part"] == "r_hear"]
    units = [g["unit"] for g in rh]
    cl = GR.cluster_table(rows, "dev")
    th_all = GR.thresholds(rows)
    nat = json.load(open(f"{RES}/readout_allclass_dev.json"))["natural"]
    th_2b = {"2b states": (nat["all-class states"]["th"]["S"], nat["all-class states"]["th"]["R"]),
             "2b ears": (nat["all-class ears"]["th"]["S"], nat["all-class ears"]["th"]["R"])}
    ro_old, ro_new = RO.load_readouts(), AC.load_allclass()
    zn = dict(np.load(f"{RO.OUT}/feats_dev_natural.npz"))
    starts = {}
    for s in CS.STARTS:
        r = CS.load_start(s)
        op = S.operating_point(rows, RO.scores_of(zn, "states", r))
        starts[f"start {s}"] = (r, (op["th_s"], op["th_r"]))
    systems = {"old head": (None, ro_old, th_all["old head"]),
               "step 2 states": ("states", ro_old, th_all["states read-out"]),
               "step 2 ears": ("ears", ro_old, th_all["read-out"]),
               "2b states": ("states", ro_new, th_2b["2b states"]),
               "2b ears": ("ears", ro_new, th_2b["2b ears"])}
    for n, (r, th) in starts.items():
        systems[n] = ("states", r, th)
    evs, evd, dsc = {}, {}, {}
    for cond in G.MATCHED:
        z = dict(np.load(f"{G.out_dir('dev')}/l1_{cond}.npz"))
        for n, (setting, r, th) in systems.items():
            sc = RO.scores_of(z, setting, r)
            dec = S.decide(sc, *th)
            evs[(n, cond)] = GR.group_eval(groups, rows_by, dec, sc)
            evd[(n, cond)] = GR.group_eval(groups, rows_by, dec, None)
            for v in ("2", "3"):
                dsc[(n, cond, v)] = np.array([sc[(g["unit"], v, g["k"])]["R"] - sc[(g["unit"], "1", g["k"])]["R"]
                                              for g in rh])
    snames = [n for n in systems if n.startswith("start ")]

    def per_unit(ev, n, field, v=None):
        if n == "control (8 starts)":
            return np.mean([per_unit(ev, m, field, v) for m in snames], 0)
        return np.array([np.mean([(ev[(n, c)][u]["pair"][v] if v else ev[(n, c)][u][field]) for c in G.MATCHED])
                         for u in units])

    def dp(n, v):
        if n == "control (8 starts)":
            return np.mean([dp(m, v) for m in snames], 0)
        return np.mean([dsc[(n, c, v)] for c in G.MATCHED], 0)

    def crit_diff(a, b):
        return ci(GR.criterion(units, cl, {}, lambda w: GR.wmean(w, a) - GR.wmean(w, b), lambda: float(a.mean() - b.mean())))

    def crit_mean(a, minus=0.0):
        return ci(GR.criterion(units, cl, {}, lambda w: GR.wmean(w, a) - minus, lambda: float(a.mean() - minus)))

    res = {"A_candidates": {}, "B_ladder": {}, "C_event_score_difference": {}, "D_cost_of_grounding": {},
           "E_answer_only": {}}

    # A. candidates
    loc = {}
    for cond in G.MATCHED:
        sc = GR.local_scores("dev", cond)
        for n in ("L2", "L3"):
            loc[(n, cond)] = GR.group_eval(groups, rows_by, S.decide(sc[n], *th_all[n]), sc[n])
    for n in ("L2", "L3"):
        a = np.array([np.mean([loc[(n, c)][u]["right"] for c in G.MATCHED]) for u in units])
        res["A_candidates"][n] = crit_mean(a)
    for n in ("old head", "step 2 states", "step 2 ears", "2b states", "2b ears"):
        res["A_candidates"][n] = crit_mean(per_unit(evs, n, "right"))
    gd, ga = json.load(open(f"{RES}/grounding_dev.json")), json.load(open(f"{RES}/grounding_allclass_dev.json"))
    res["A_candidates"]["combination"] = ci(gd["criteria"]["G1a combination: grounded group accuracy (lower bound > 0.50)"])
    res["A_candidates"]["step 2 conditional"] = ci(gd["criteria"]["G1a conditional: grounded group accuracy (lower bound > 0.50)"])
    res["A_candidates"]["2b conditional"] = ci(ga["criteria"]["G1a 2b conditional: R-hear grounded group accuracy (lower bound > 0.50)"])
    rd = json.load(open(f"{RES}/readout_dev.json"))["settings"]
    natural = {"old head": json.load(open(f"{RES}/decision_dev_dryrun_l1.json"))["systems"]["L1"]["primary"],
               "L2": json.load(open(f"{RES}/decision_dev_dryrun_l1.json"))["systems"]["L2"]["primary"],
               "L3": json.load(open(f"{RES}/decision_dev_dryrun_l1.json"))["systems"]["L3"]["primary"],
               "combination": json.load(open(f"{RES}/decision_dev_dryrun_combination.json"))["systems"]["L1"]["primary"],
               "step 2 states": rd["states"]["natural"]["primary"], "step 2 ears": rd["ears"]["natural"]["primary"],
               "step 2 conditional": json.load(open(f"{RES}/conditional_dev.json"))["inputs"]["natural"]["primary"],
               "2b states": nat["all-class states"]["primary"], "2b ears": nat["all-class ears"]["primary"],
               "2b conditional": nat["all-class conditional"]["primary"]}
    for n, v in natural.items():
        res["A_candidates"][n]["natural_five_part_mean"] = v
        res["A_candidates"][n]["passes_G1a"] = res["A_candidates"][n]["ci95"][0] > 0.5
        res["A_candidates"][n]["not_below_old_head"] = v >= natural["old head"]

    # B. ladder, score and decision level
    ctl = "control (8 starts)"
    for level, ev in (("score", evs), ("decision", evd)):
        L = {}
        for n in (ctl, "old head", "step 2 states", "2b states", "2b ears"):
            L[f"{n}: presence (1 vs 2)"] = float(per_unit(ev, n, None, "2").mean())
            L[f"{n}: identity (1 vs 3)"] = float(per_unit(ev, n, None, "3").mean())
            L[f"{n}: conc"] = float(per_unit(ev, n, "conc").mean())
        L["G2b: 2b states - control (conc)"] = crit_diff(per_unit(ev, "2b states", "conc"), per_unit(ev, ctl, "conc"))
        L["G3a: step 2 states - control (presence)"] = crit_diff(per_unit(ev, "step 2 states", None, "2"),
                                                                 per_unit(ev, ctl, None, "2"))
        L["G3a absolute: step 2 states presence - 0.5"] = crit_mean(per_unit(ev, "step 2 states", None, "2"), 0.5)
        L["G3b: 2b states - step 2 states (identity)"] = crit_diff(per_unit(ev, "2b states", None, "3"),
                                                                   per_unit(ev, "step 2 states", None, "3"))
        L["G3b absolute: 2b states identity - 0.5"] = crit_mean(per_unit(ev, "2b states", None, "3"), 0.5)
        L["side rung 1: identity change, step 2 states - control"] = crit_diff(per_unit(ev, "step 2 states", None, "3"),
                                                                               per_unit(ev, ctl, None, "3"))
        L["side rung 2: presence change, 2b states - step 2 states"] = crit_diff(per_unit(ev, "2b states", None, "2"),
                                                                                 per_unit(ev, "step 2 states", None, "2"))
        L["main system presence - 0.5"] = crit_mean(per_unit(ev, "2b ears", None, "2"), 0.5)
        L["main system identity - 0.5"] = crit_mean(per_unit(ev, "2b ears", None, "3"), 0.5)
        res["B_ladder"][level] = L

    # C. event-score differences (positive = the event version gets the higher event score)
    for n in (ctl, "old head", "step 2 states", "2b states", "2b ears"):
        for v, lab in (("2", "presence"), ("3", "identity")):
            res["C_event_score_difference"][f"{n}: {lab}"] = crit_mean(dp(n, v))
    for v, lab in (("2", "presence"), ("3", "identity")):
        res["C_event_score_difference"][f"rung 1 step 2 states - control: {lab}"] = crit_diff(dp("step 2 states", v), dp(ctl, v))
        res["C_event_score_difference"][f"rung 2 2b states - step 2 states: {lab}"] = crit_diff(dp("2b states", v),
                                                                                             dp("step 2 states", v))

    # D. cost of grounding on natural dev
    drows = D.load_rows("dev")
    sg = S.load_groups("dev")
    dec_s2 = S.decide(GR.keyed(json.load(open(f"{RO.OUT}/scores_dev_readout.json"))), *th_all["read-out"])
    dec_2b = S.decide(RO.scores_of(zn, "ears", ro_new), *th_2b["2b ears"])
    Ta, Tb = S.unit_table(drows, dec_s2, sg), S.unit_table(drows, dec_2b, sg)
    c = S.interval(Ta, Tb, "primary")
    res["D_cost_of_grounding"] = {"step 2 ears": S.metrics(Ta)["primary"], "2b ears": S.metrics(Tb)["primary"],
                                  "difference": {"point": c["point"], "ci95": c["ci95"]}}

    # E. answer-only losses
    pa = json.load(open(f"{RES}/decision_dev_dryrun_allclass_ears.json"))["systems"]
    an = json.load(open(f"{RES}/decision_dev_dryrun_allclass_ears_answers.json"))["systems"]
    for r in ("B2-fast", "B2-strong", "B3"):
        res["E_answer_only"][r] = {
            "five_part_mean": {"probabilities": pa[r]["primary"], "answers": an[r]["primary"],
                               "loss_points": 100 * (pa[r]["primary"] - an[r]["primary"])},
            "must_listen": {"probabilities": pa[r]["audio"], "answers": an[r]["audio"],
                            "loss_points": 100 * (pa[r]["audio"] - an[r]["audio"])},
            "floor_mean_5": {"probabilities": pa[r].get("floor_mean_5"), "answers": an[r].get("floor_mean_5")}}
    json.dump(res, open(f"{RES}/amendment_numbers_dev.json", "w"), indent=1)

    def fmt(x):
        return f"{x['point']:+.3f} [{x['ci95'][0]:+.3f}, {x['ci95'][1]:+.3f}]"
    for n, x in res["A_candidates"].items():
        print(f"A {n:20s} G1a {x['point']:.3f} [{x['ci95'][0]:.3f}, {x['ci95'][1]:.3f}] natural "
              f"{x['natural_five_part_mean']:.3f} passes {x['passes_G1a']} not below old head {x['not_below_old_head']}")
    for level, L in res["B_ladder"].items():
        for k, v in L.items():
            print(f"B {level:8s} {k}: " + (fmt(v) if isinstance(v, dict) else f"{v:.3f}"))
    for k, v in res["C_event_score_difference"].items():
        print(f"C {k}: {fmt(v)}")
    d = res["D_cost_of_grounding"]
    print(f"D step 2 ears {d['step 2 ears']:.4f} 2b ears {d['2b ears']:.4f} diff {fmt(d['difference'])}")
    for r, x in res["E_answer_only"].items():
        print(f"E {r}: " + json.dumps({k: {kk: (round(vv, 4) if isinstance(vv, float) else vv) for kk, vv in v.items()}
                                       for k, v in x.items()}))


if __name__ == "__main__":
    main()
